package tw.com.tft.documentscanner.imaging;import org.opencv.core.*;import org.opencv.imgproc.*;import java.util.*;import tw.com.tft.documentscanner.model.FilterMode;public final class ImageEnhancer{public static Mat apply(Mat b,FilterMode m){if(m==null||m==FilterMode.ORIGINAL)return b.clone();if(m==FilterMode.BLACK_WHITE)return bw(b);return lab(b,m==FilterMode.SOFT_WHITE);}private static Mat lab(Mat b,boolean soft){Mat l=new Mat();Imgproc.cvtColor(b,l,Imgproc.COLOR_BGR2Lab);List<Mat>c=new ArrayList<>();Core.split(l,c);CLAHE cl=Imgproc.createCLAHE(soft?1.7:2.4,new Size(8,8));Mat x=new Mat();cl.apply(c.get(0),x);Mat il=new Mat();Imgproc.GaussianBlur(x,il,new Size(0,0),soft?34:18);Mat cor=new Mat();Core.addWeighted(x,soft?1.16:1.24,il,soft?-.16:-.24,soft?18:6,cor);c.set(0,cor);Mat mer=new Mat();Core.merge(c,mer);Mat out=new Mat();Imgproc.cvtColor(mer,out,Imgproc.COLOR_Lab2BGR);l.release();x.release();il.release();mer.release();for(int i=1;i<c.size();i++)c.get(i).release();cor.release();return out;}private static Mat bw(Mat b){Mat g=new Mat();Imgproc.cvtColor(b,g,Imgproc.COLOR_BGR2GRAY);Mat il=new Mat();Imgproc.GaussianBlur(g,il,new Size(0,0),22);Mat n=new Mat();Core.divide(g,il,n,220.0);Mat q=new Mat();Imgproc.adaptiveThreshold(n,q,255,Imgproc.ADAPTIVE_THRESH_GAUSSIAN_C,Imgproc.THRESH_BINARY,31,10);Mat o=new Mat();Imgproc.cvtColor(q,o,Imgproc.COLOR_GRAY2BGR);g.release();il.release();n.release();q.release();return o;}}